class LibraryMember{protected String memberId;protected int borrowLimit,booksBorrowed;public LibraryMember(String id,int l){if(id==null||id.trim().length()<4||l<=0)throw new IllegalArgumentException("Invalid member details");memberId=id;borrowLimit=l;booksBorrowed=0;}public void borrowBook(){if(booksBorrowed<borrowLimit)booksBorrowed++;}public int getBooksBorrowed(){return booksBorrowed;}public void displayInfo(){System.out.println("General Member | Books Borrowed: "+booksBorrowed);}}
class StudentMember extends LibraryMember{protected String course;public StudentMember(String id,int l,String c){super(id,l);course=c;}public void displayInfo(){System.out.println("Student Member | Course: "+course+" | Books Borrowed: "+getBooksBorrowed());}}
class HonorsStudentMember extends StudentMember{private int bonusLimit;public HonorsStudentMember(String id,int l,String c,int b){super(id,l,c);if(b<0)throw new IllegalArgumentException("Invalid bonus limit");bonusLimit=b;}public void borrowBook(){if(booksBorrowed<borrowLimit+bonusLimit)booksBorrowed++;}public void displayInfo(){System.out.println("Honors Student Member | Course: "+course+" | Bonus Limit: "+bonusLimit+" | Books Borrowed: "+getBooksBorrowed());}}
class FacultyMember extends LibraryMember{private String department;public FacultyMember(String id,int l,String d){super(id,l);department=d;}public void displayInfo(){System.out.println("Faculty Member | Department: "+department+" | Books Borrowed: "+getBooksBorrowed());}}
public class MembershipTree{static String classifyGeneration(LibraryMember m){if(m instanceof HonorsStudentMember)return "Multilevel descendant (3 generations deep)";if(m instanceof FacultyMember)return "Hierarchical sibling (independent branch)";if(m instanceof StudentMember)return "Second generation (Student Member)";return "Base generation (Library Member)";}static int getTotalBooksBorrowed(LibraryMember[] a){int n=0;for(LibraryMember m:a)n+=m.getBooksBorrowed();return n;}public static void main(String[] args){LibraryMember g=new LibraryMember("LIB1",3);StudentMember s=new StudentMember("STU1",3,"CSE");HonorsStudentMember h=new HonorsStudentMember("STU2",3,"ECE",2);FacultyMember f=new FacultyMember("FAC1",5,"Physics");s.borrowBook();s.borrowBook();h.borrowBook();f.borrowBook();f.borrowBook();f.borrowBook();g.displayInfo();s.displayInfo();h.displayInfo();f.displayInfo();System.out.println(classifyGeneration(h));System.out.println(classifyGeneration(f));System.out.println(getTotalBooksBorrowed(new LibraryMember[]{s,h,f}));}}